                else if (nextChar == 'o')
                {
                    // Octal number
                    Advance(); // Skip '0'
                    Advance(); // Skip 'o' or 'O'
                    while (_position < _source.Length && (CurrentChar >= '0' && CurrentChar <= '7' || CurrentChar == '_'))
                    {
                        Advance();
                    }
                }
                else if (nextChar == 'b')
                {
                    // Binary number
                    Advance(); // Skip '0'
                    Advance(); // Skip 'b' or 'B'
                    while (_position < _source.Length && (CurrentChar == '0' || CurrentChar == '1' || CurrentChar == '_'))
                    {
                        Advance();
                    }
                }
                else
